const referencesInput=document.querySelector('#references-input');const productsInput=document.querySelector('#products-input');const status=document.querySelector('#save-status');
function lines(value){return value.split('\n').map((item)=>item.trim()).filter(Boolean)}function fillFields(content){referencesInput.value=content.references.join('\n');productsInput.value=content.products.join('\n');updateCounts()}function updateCounts(){document.querySelector('#references-count').textContent=`${lines(referencesInput.value).length}개`;document.querySelector('#products-count').textContent=`${lines(productsInput.value).length}개`}function currentContent(){return{references:lines(referencesInput.value),products:lines(productsInput.value)}}
referencesInput.addEventListener('input',updateCounts);productsInput.addEventListener('input',updateCounts);document.querySelector('#save-content').addEventListener('click',()=>{localStorage.setItem('hmit-content',JSON.stringify(currentContent()));status.textContent='저장되었습니다. 홈페이지를 새로 열면 변경 내용이 표시됩니다.'});document.querySelector('#export-content').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(currentContent(),null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='hmit-content.json';link.click();URL.revokeObjectURL(link.href);status.textContent='설정 파일을 내려받았습니다.'});document.querySelector('#reset-content').addEventListener('click',()=>{localStorage.removeItem('hmit-content');fillFields(HM_CONTENT_DEFAULTS);status.textContent='기본 목록으로 되돌렸습니다.'});fillFields(getHmContent());
